INSERT INTO jobs (recruiter_id, title, description, location)
VALUES ((SELECT id FROM recruiter_profiles ORDER BY id LIMIT 1),
        'Final Demo Job', 'DBMS demonstration', 'Bengaluru');
SET @demo_job_id = LAST_INSERT_ID();

SELECT id, title, location FROM jobs WHERE id = @demo_job_id;
UPDATE jobs SET location = 'Hyderabad' WHERE id = @demo_job_id;
DELETE FROM jobs WHERE id = @demo_job_id;

ALTER TABLE jobs
MODIFY COLUMN salary VARCHAR(150) NULL DEFAULT 'Not disclosed';

CREATE OR REPLACE VIEW job_application_summary AS
SELECT j.id AS job_id, j.title, r.company_name,
       COUNT(a.id) AS applicant_count
FROM jobs j
JOIN recruiter_profiles r ON r.id = j.recruiter_id
LEFT JOIN applications a ON a.job_id = j.id
GROUP BY j.id, j.title, r.company_name;

SELECT * FROM job_application_summary;
